   206    protected:
   207    Tag           sfnt_version;   /* '\0\001\0\00' if TrueType / 'OTTO' if CFF */
   208    BinSearchArrayOf<TableRecord>
   209                  tables;
   210    public:
   211    DEFINE_SIZE_ARRAY (12, tables);
